settings.custom_liquid:
{%- comment -%}
  Parent Collection Breadcrumb (i18n)
  - Uniform typography everywhere (same size & font)
  - Localized "Category" label
  - No clickable items
  - Max width: 1200px
  - Desktop: no left padding
  - Mobile: Dawn-like padding
  - Color: #BF1E2D
  - Font size: 16px (everywhere)
  - JSON-LD included
{%- endcomment -%}

{%- assign locale = request.locale.iso_code | downcase -%}

{%- assign bc_label = 'Category:' -%}

{%- case locale -%}
  {%- when 'de' -%}
    {%- assign bc_label = 'Kategorie:' -%}
  {%- when 'nl' -%}
    {%- assign bc_label = 'Categorie:' -%}
  {%- when 'fr' -%}
    {%- assign bc_label = 'Catégorie:' -%}
  {%- when 'es' -%}
    {%- assign bc_label = 'Categoría:' -%}
  {%- when 'it' -%}
    {%- assign bc_label = 'Categoria:' -%}
  {%- when 'sv-se' -%}
    {%- assign bc_label = 'Kategori:' -%}
  {%- when 'da-dk' -%}
    {%- assign bc_label = 'Kategori:' -%}
  {%- when 'no' -%}
    {%- assign bc_label = 'Kategori:' -%}
{%- endcase -%}

<div class="breadcrumbs-wrap">
  <nav class="breadcrumbs" aria-label="Breadcrumb">
    <span class="breadcrumbs__label">{{ bc_label }}</span>

    <ol class="breadcrumbs__list" role="list">
      <li class="breadcrumbs__item">
        <span class="breadcrumbs__current" aria-current="page">
          {{ collection.title }}
        </span>
      </li>
    </ol>
  </nav>
</div>

<script type="application/ld+json">
{
  "@context": "https://schema.org",
  "@type": "BreadcrumbList",
  "itemListElement": [
    {
      "@type": "ListItem",
      "position": 1,
      "name": {{ collection.title | json }},
      "item": "{{ shop.url }}{{ collection.url }}"
    }
  ]
}
</script>

<style>
  .breadcrumbs-wrap {
    max-width: 1200px;
    margin: 0 auto;
    padding: 0;
  }

  /* Mobile padding like Dawn */
  @media screen and (max-width: 749px) {
    .breadcrumbs-wrap {
      padding-left: 2rem;
      padding-right: 2rem;
    }
  }

  .breadcrumbs {
    display: flex;
    align-items: center;
    gap: 8px;
    margin: 0;
    padding: 0;

    font-family: inherit;
    font-size: 16px;       /* SAME everywhere */
    font-weight: 400;      /* SAME everywhere */
    line-height: 1.2;
    color: #BF1E2D;
  }

  .breadcrumbs__label {
    font-size: 16px;       /* SAME */
    font-weight: 400;      /* SAME */
    opacity: 1;          /* only visual distinction */
    white-space: nowrap;
  }

  .breadcrumbs__list {
    display: flex;
    gap: 8px;
    padding: 0;
    margin: 0;
    list-style: none;
  }

  .breadcrumbs__current {
    font-size: 16px;       /* SAME */
    font-weight: 400;      /* SAME */
    color: #BF1E2D;
  }
</style>
